(194925, 11136, 4813, '<td valign="top">I like it</td>', 'I like it', '2003-01-20 00:45:22.000000', NULL, 1),
(194927, 11296, 3280, '<td valign="top">Really neat idea, it just seems a bit blurry.</td>', 'Really neat idea, it just seems a bit blurry.', '2003-01-20 00:46:12.000000', NULL, 1),
