(194930, 11132, 5700, '<td valign="top">Looks really cool, how''d you do it?</td>', 'Looks really cool, how''d you do it?', '2003-01-20 00:47:19.000000', NULL, 1),
(194931, 11245, 3280, '<td valign="top">Cool idea, it seems a bit too red though.</td>', 'Cool idea, it seems a bit too red though.', '2003-01-20 00:47:29.000000', NULL, 1),
