(195613, 11098, 2058, '<td valign="top">The motion blur here makes the photo I think.  Nice color in the sky too :) 8</td>', 'The motion blur here makes the photo I think.  Nice color in the sky too :) 8', '2003-01-20 11:15:13.000000', NULL, 1),
(195614, 11137, 3607, '<td valign="top">a runner in the photo would have made it much more powerful</td>', 'a runner in the photo would have made it much more powerful', '2003-01-20 11:16:20.000000', NULL, 1),
(195616, 11324, 2058, '<td valign="top">:)  Have people run this stop sign?  Nice image... it would be nice if you could see more of the drop off, that might give the photo a little more impact.  7</td>', ':)  Have people run this stop sign?  Nice image... it would be nice if you could see more of the drop off, that might give the photo a little more impact.  7', '2003-01-20 11:17:25.000000', NULL, 1),
