INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(200026, 11134, 6087, '<td valign="top">Good shot.</td>', 'Good shot.', '2003-01-26 03:00:53.000000', NULL, 1),
(200027, 11051, 6087, '<td valign="top">I like the details, nice picture.</td>', 'I like the details, nice picture.', '2003-01-26 03:02:13.000000', NULL, 1),
(200028, 11244, 3273, '<td valign="top">Nice idea makes it stand apart from the other STOP signs.  Clairty and definition is good, I do wonder what it would have been like in colour though.  The subtle border adds nicely to the shot too!</td>', 'Nice idea makes it stand apart from the other STOP signs.  Clairty and definition is good, I do wonder what it would have been like in colour though.  The subtle border adds nicely to the shot too!', '2003-01-26 04:18:13.000000', NULL, 1),
(200029, 11300, 3273, '<td valign="top">This is a really moody shot.  The eyes seem to be drawn towards the single bright light on the far corner of the building.  The only problem is the spot near the top centre of the frame, is it rain on the lens?</td>', 'This is a really moody shot.  The eyes seem to be drawn towards the single bright light on the far corner of the building.  The only problem is the spot near the top centre of the frame, is it rain on the lens?', '2003-01-26 04:23:10.000000', NULL, 1),
(200030, 11142, 3273, '<td valign="top">Nice viewpoint.  The only thing I don''t like about this photo is the reflection of the light on the Give Way sign, it''s a shame that the light was on.</td>', 'Nice viewpoint.  The only thing I don''t like about this photo is the reflection of the light on the Give Way sign, it''s a shame that the light was on.', '2003-01-26 04:25:17.000000', NULL, 1),
(200031, 11134, 3273, '<td valign="top">Great clarity and definition.  Something isn''t quite right about the circle inside the rectangle, I think I would either have liked black space all the way around the circle or for it to be more tightly cropped on the left and right.</td>', 'Great clarity and definition.  Something isn''t quite right about the circle inside the rectangle, I think I would either have liked black space all the way around the circle or for it to be more tightly cropped on the left and right.', '2003-01-26 04:29:44.000000', NULL, 1),
(200032, 11182, 3273, '<td valign="top">There''s a nice tone to this shot and I like the viewpoint you chose, looking upward.  The composition is excellent and you''ve made good use of the space available in the frame.</td>', 'There''s a nice tone to this shot and I like the viewpoint you chose, looking upward.  The composition is excellent and you''ve made good use of the space available in the frame.', '2003-01-26 04:31:53.000000', NULL, 1),
(200033, 11223, 3273, '<td valign="top">I like this one.  I''m not sure whether to laugh at it or cry though!  The sky seems a little harsh and I''m not sure about the contrast on some of the branches.  Excellent shot though and a really good composition.</td>', 'I like this one.  I''m not sure whether to laugh at it or cry though!  The sky seems a little harsh and I''m not sure about the contrast on some of the branches.  Excellent shot though and a really good composition.', '2003-01-26 04:33:22.000000', NULL, 1),
(200035, 11185, 3273, '<td valign="top">Nice photo.  I think it would have been better to include the top of the sign rather than cropping it off but it''s still a good shot.  I like the lack of colour in the background buildings but I keep being drawn towards the little red light on the building on the left.</td>', 'Nice photo.  I think it would have been better to include the top of the sign rather than cropping it off but it''s still a good shot.  I like the lack of colour in the background buildings but I keep being drawn towards the little red light on the building on the left.', '2003-01-26 04:42:02.000000', NULL, 1),
(200043, 11118, 4510, '<td valign="top">Nice sky and funny to, good luck:)</td>', 'Nice sky and funny to, good luck:)', '2003-01-26 06:55:34.000000', NULL, 1),
